import{_ as t,o,c as n,a2 as i}from"./chunks/framework.Crpw6aS5.js";const h=JSON.parse('{"title":"Public Documentation Contract","description":"","frontmatter":{},"headers":[],"relativePath":"AGENTS.md","filePath":"AGENTS.md","lastUpdated":1783686541000}'),a={name:"AGENTS.md"};function r(s,e,c,l,d,u){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="public-documentation-contract" tabindex="-1">Public Documentation Contract <a class="header-anchor" href="#public-documentation-contract" aria-label="Permalink to &quot;Public Documentation Contract&quot;">​</a></h1><p>The <code>docs/</code> tree is published to product users. Write only about installed or released behavior, setup, usage, troubleshooting, and stable public reference material.</p><ul><li>Do not place roadmaps, implementation plans, agent handoffs, internal test counts, unreleased API contracts, release secrets, Git/tag procedures, or maintainer-only runbooks here.</li><li>Put internal architecture decisions, migration plans, validation matrices, and release operations under <code>maintainers/</code>.</li><li>Keep version-specific user-visible changes in <code>release-notes/</code>.</li><li>A maintainer plan may produce a separate user guide after a feature ships; do not publish the internal plan itself.</li><li>Keep Chinese pages and their <code>docs/en/</code> counterparts aligned when both versions exist.</li><li>Preserve VitePress structure and existing terminology; do not replace reference screenshots or media unless the task requires it.</li><li>Run <code>bun run check:docs</code> for public documentation changes. Maintainer-only Markdown does not require a VitePress build unless it changes links or repository tooling.</li><li><code>check:docs</code> runs <code>npm ci</code> and may rebuild root <code>node_modules</code>; run it sequentially with other checks that use the root dependency tree.</li><li>Keep public update guidance consistent with <code>scripts/release.ts</code>, <code>.github/workflows/release-desktop.yml</code>, and versioned release notes without publishing maintainer-only release operations.</li></ul>',3)])])}const m=t(a,[["render",r]]);export{h as __pageData,m as default};
